fn code_of(c: Str) -> Int {
  return c.codes().get_or(0, 0)
}

fn is_space(c: Str) -> Bool {
  let k = code_of(c)
  return k == 32 or k == 9 or k == 10 or k == 13
}

fn is_digit_c(c: Str) -> Bool {
  let k = code_of(c)
  return k >= 48 and k <= 57
}

fn is_ident_start(c: Str) -> Bool {
  let k = code_of(c)
  return (k >= 97 and k <= 122) or (k >= 65 and k <= 90) or k == 95
}

fn is_single(c: Str) -> Bool {
  return c == "+" or c == "-" or c == "*" or c == "/" or c == "<" or c == ">" or c == "=" or c == "(" or c == ")" or c == "{" or c == "}" or c == "," or c == ";"
}

fn is_two(c: Str, d: Str) -> Bool {
  let p = c + d
  return p == "==" or p == "!=" or p == "<=" or p == ">=" or p == "->"
}

pub fn tokens(src: Str) -> Result[List[Str], Str] {
  let cs = src.chars()
  let n = cs.len()
  var out: List[Str] = []
  var i = 0
  while i < n {
    let c = cs.get_or(i, "")
    let nxt = cs.get_or(i + 1, "")
    if is_space(c) {
      i = i + 1
    } else if is_ident_start(c) {
      var id_end = i + 1
      while id_end < n and (is_ident_start(cs.get_or(id_end, "")) or is_digit_c(cs.get_or(id_end, ""))) {
        id_end = id_end + 1
      }
      out = out.push(cs.slice(i, id_end).join(""))
      i = id_end
    } else if is_digit_c(c) {
      var num_end = i + 1
      while num_end < n and is_digit_c(cs.get_or(num_end, "")) {
        num_end = num_end + 1
      }
      out = out.push(cs.slice(i, num_end).join(""))
      i = num_end
    } else if c == "\"" {
      var str_end = i + 1
      while str_end < n and cs.get_or(str_end, "") != "\"" {
        if cs.get_or(str_end, "") == "\\" {
          str_end = str_end + 2
        } else {
          str_end = str_end + 1
        }
      }
      if str_end >= n {
        return Err("unterminated string")
      }
      out = out.push(cs.slice(i, str_end + 1).join(""))
      i = str_end + 1
    } else if is_two(c, nxt) {
      out = out.push(c + nxt)
      i = i + 2
    } else if is_single(c) {
      out = out.push(c)
      i = i + 1
    } else {
      return Err("unexpected {c}")
    }
  }
  return Ok(out)
}
